package com.circlenet.domain.trust;
import jakarta.persistence.*; import java.time.Instant;
@Entity @Table(name="role_model_follows",uniqueConstraints=@UniqueConstraint(columnNames={"follower_user_id","role_model_user_id"})) public class RoleModelFollowEntity {@Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id;@Column(name="follower_user_id",nullable=false) private Long followerUserId;@Column(name="role_model_user_id",nullable=false) private Long roleModelUserId;@Column(name="created_at",nullable=false) private Instant createdAt=Instant.now();public Long getId(){return id;}public Long getFollowerUserId(){return followerUserId;}public void setFollowerUserId(Long v){followerUserId=v;}public Long getRoleModelUserId(){return roleModelUserId;}public void setRoleModelUserId(Long v){roleModelUserId=v;}public Instant getCreatedAt(){return createdAt;}}
